/** Built-in message templates, used as fallback and seeded into MessageTemplate. Cyrillic is generated by transliteration in the seed. */
export const TEMPLATE_KEYS = ['OTP', 'WELCOME', 'RECEIPT', 'EXPIRY', 'ABANDONED', 'WINBACK', 'STREAK', 'REFERRAL'] as const;
export type TemplateKey = (typeof TEMPLATE_KEYS)[number];

export const TEMPLATE_VARS: Record<TemplateKey, string[]> = {
  OTP: ['code'],
  WELCOME: ['name', 'promo_code'],
  RECEIPT: ['name', 'plan', 'amount', 'expiry_date'],
  EXPIRY: ['name', 'expiry_date'],
  ABANDONED: ['name', 'plan', 'promo_code'],
  WINBACK: ['name', 'promo_code'],
  STREAK: ['name', 'streak'],
  REFERRAL: ['name', 'days'],
};

